import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';

@Component({
  selector: 'app-dashboard-home',
  templateUrl: './dashboard-home.component.html',
  styleUrls: ['./dashboard-home.component.css']
})
export class DashboardHomeComponent implements OnInit {
  userRole: string = '';
  currentUser: any = null;

  constructor(private router: Router) {}

  ngOnInit(): void {
    // قراءة بيانات المستخدم لمعرفة الـ Role
    const userData = localStorage.getItem('user');
    if (userData) {
      this.currentUser = JSON.parse(userData);
      this.userRole = this.currentUser.role ? this.currentUser.role.toLowerCase() : '';
    }
  }

  // 1️⃣ فانكشن إضافة طالب
  addStudent(): void {
    this.router.navigate(['/dashboard/students']);
  }

  // 2️⃣ فانكشن إضافة مدرس (للأدمن فقط)
  addTeacher(): void {
    this.router.navigate(['/dashboard/teachers']);
  }

  // 3️⃣ فانكشن تسجيل الحضور
  takeAttendance(): void {
    this.router.navigate(['/dashboard/attendance']);
  }

  // 4️⃣ فانكشن تسجيل الدفع
  recordPayment(): void {
    this.router.navigate(['/dashboard/payments']);
  }
}
